#!/usr/bin/env node
// Bundles src/services/checkoutV2/bundleEntry.ts (the pure session-binding, pricing,
// status-mapping, idempotency and email-payload logic behind create-auth-hold-v2 /
// verify-payment-v2 — see S1-LIVE-CHECKOUT-FIX) into a single Deno-importable ESM file at
// supabase/functions/_shared/checkout-v2.bundle.js, plus a matching .d.ts declaration file.
//
// Same approach as scripts/metro/export-metro-checkout-bundle.mjs (esbuild is already a
// transitive Vite dependency; no new dependency added). Unlike metro's bundle, checkoutV2 has no
// dependency on the generated Supabase `Database` type, so the .d.ts here is emitted as one flat
// `tsc --emitDeclarationOnly` pass over bundleEntry.ts's whole dependency graph and inlined
// verbatim — no cherry-picking needed.
//
// Run manually with `node scripts/checkout/export-checkout-v2-bundle.mjs` any time
// src/services/checkoutV2/** (or src/utils/emailTemplates.ts, which it re-exports from) changes,
// and before `supabase functions deploy create-auth-hold-v2` / `verify-payment-v2`. A vitest
// parity test (src/services/checkoutV2/bundleParity.test.ts) fails loudly with a reminder to
// re-run this script if the checked-in bundle drifts from source.

import { build } from 'esbuild';
import ts from 'typescript';
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync, existsSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(__dirname, '..', '..');

const entry = path.join(repoRoot, 'src', 'services', 'checkoutV2', 'bundleEntry.ts');
const outDir = path.join(repoRoot, 'supabase', 'functions', '_shared');
const outFile = path.join(outDir, 'checkout-v2.bundle.js');
const dtsOutFile = path.join(outDir, 'checkout-v2.bundle.d.ts');

const banner = `// AUTO-GENERATED by scripts/checkout/export-checkout-v2-bundle.mjs — DO NOT EDIT BY HAND.
// Source: src/services/checkoutV2/bundleEntry.ts (re-exports contract/pricing/metadata/binding/
// statusMapping/idempotency/emailPayload/orderRecords + src/utils/emailTemplates.ts)
// Regenerate: node scripts/checkout/export-checkout-v2-bundle.mjs
// Generated: ${new Date().toISOString()}
`;

async function main() {
  mkdirSync(outDir, { recursive: true });

  await build({
    entryPoints: [entry],
    outfile: outFile,
    bundle: true,
    platform: 'neutral',
    format: 'esm',
    target: 'es2022',
    logLevel: 'warning',
    banner: { js: banner },
  });

  console.log(`Wrote checkout-v2 bundle -> ${path.relative(repoRoot, outFile)}`);

  emitDeclarations();
}

// Every module bundleEntry.ts re-exports from, in dependency order (contract.ts first — it has
// no internal imports; everything else imports from it — then the rest, then the
// zero-import emailTemplates.ts last). All of these are self-contained (no dependency on the
// generated Supabase `Database` type, unlike metro's bundle), so — unlike
// scripts/metro/export-metro-checkout-bundle.mjs, which cherry-picks individual interfaces out
// of files it can't safely inline whole — every file here is inlined in full. Each file's
// tsc-emitted `import ... from './sibling'` line (referencing another module in this same list)
// is stripped, since after concatenation every name it would have imported is already in scope
// earlier in the same flat file.
const DTS_MODULES = [
  'services/checkoutV2/contract.ts',
  'services/checkoutV2/pricing.ts',
  'services/checkoutV2/metadata.ts',
  'services/checkoutV2/binding.ts',
  'services/checkoutV2/statusMapping.ts',
  'services/checkoutV2/idempotency.ts',
  'services/checkoutV2/emailPayload.ts',
  'services/checkoutV2/orderRecords.ts',
  'utils/emailTemplates.ts',
];

const SIBLING_IMPORT_RE = /^import\s+(?:type\s+)?\{[^}]*\}\s+from\s+'\.\/(?:contract|pricing|metadata|binding|statusMapping|idempotency|emailPayload|orderRecords)';\s*$/gm;

function emitDeclarations() {
  const tmpDir = mkdtempSync(path.join(os.tmpdir(), 'mgg-checkout-v2-dts-'));
  try {
    const srcDir = path.join(repoRoot, 'src');
    const compilerOptions = {
      target: ts.ScriptTarget.ES2020,
      module: ts.ModuleKind.ESNext,
      moduleResolution: ts.ModuleResolutionKind.Bundler,
      declaration: true,
      emitDeclarationOnly: true,
      skipLibCheck: true,
      strict: false,
      noImplicitAny: false,
      outDir: tmpDir,
      rootDir: srcDir,
    };

    const program = ts.createProgram([entry], compilerOptions);
    const emitResult = program.emit();
    const diagnostics = [...ts.getPreEmitDiagnostics(program), ...emitResult.diagnostics];
    if (diagnostics.length > 0) {
      const formatted = ts.formatDiagnosticsWithColorAndContext(diagnostics, {
        getCurrentDirectory: () => repoRoot,
        getCanonicalFileName: (f) => f,
        getNewLine: () => ts.sys.newLine,
      });
      throw new Error(
        `TypeScript declaration emit for checkout-v2.bundle.d.ts reported diagnostics (fix the source, or this .d.ts would silently be wrong):\n${formatted}`,
      );
    }

    const sections = DTS_MODULES.map((rel) => {
      const dtsPath = path.join(tmpDir, rel.replace(/\.ts$/, '.d.ts'));
      if (!existsSync(dtsPath)) {
        throw new Error(`Expected declaration output at ${dtsPath} (for src/${rel}) but it was not emitted.`);
      }
      const raw = readFileSync(dtsPath, 'utf8');
      const stripped = raw.replace(SIBLING_IMPORT_RE, '').trim();
      return `// ─── from src/${rel} ───\n${stripped}`;
    });

    const dtsBanner = `// AUTO-GENERATED by scripts/checkout/export-checkout-v2-bundle.mjs — DO NOT EDIT BY HAND.
// Type declarations for checkout-v2.bundle.js. Real tsc --emitDeclarationOnly output for each
// module src/services/checkoutV2/bundleEntry.ts re-exports (tsc-verified, not hand-duplicated),
// inlined in dependency order with intra-package imports stripped (see DTS_MODULES in
// scripts/checkout/export-checkout-v2-bundle.mjs).
// Regenerate: node scripts/checkout/export-checkout-v2-bundle.mjs
// Generated: ${new Date().toISOString()}
`;

    writeFileSync(dtsOutFile, `${dtsBanner}\n${sections.join('\n\n')}\n`);
    console.log(`Wrote checkout-v2 bundle declarations -> ${path.relative(repoRoot, dtsOutFile)}`);
  } finally {
    rmSync(tmpDir, { recursive: true, force: true });
  }
}

main().catch((err) => {
  console.error('export-checkout-v2-bundle failed:', err);
  process.exitCode = 1;
});
